//! Tiny client for accounts-daemon on the system bus.
//! No policy in here, the caller decides if a change is ok

use color_eyre::{
    Result,
    eyre::{Context as _, eyre},
};

#[expect(clippy::same_name_method, reason = "code generated by zbus::proxy")]
mod proxy {
    #[zbus::proxy(
        interface = "org.freedesktop.Accounts",
        default_service = "org.freedesktop.Accounts",
        default_path = "/org/freedesktop/Accounts"
    )]
    pub trait Accounts {
        fn find_user_by_name(&self, name: &str) -> zbus::Result<zbus::zvariant::OwnedObjectPath>;
    }

    #[zbus::proxy(
        interface = "org.freedesktop.Accounts.User",
        default_service = "org.freedesktop.Accounts"
    )]
    pub trait AccountsUser {
        fn set_password(&self, password: &str, hint: &str) -> zbus::Result<()>;

        #[zbus(property)]
        fn uid(&self) -> zbus::Result<u64>;

        #[zbus(property)]
        fn system_account(&self) -> zbus::Result<bool>;

        #[zbus(property)]
        fn local_account(&self) -> zbus::Result<bool>;
    }
}
use proxy::{AccountsProxy, AccountsUserProxy};

/// Info about a local account, straight from accounts-daemon
#[derive(Debug, Clone)]
pub struct AccountInfo {
    pub uid: u64,
    pub system_account: bool,
    pub local_account: bool,
}

/// Handle to one user in accounts-daemon
pub struct Account {
    proxy: AccountsUserProxy<'static>,
}

impl Account {
    /// Look up a user by name.
    /// Fails if accounts-daemon isn't running or the user doesn't exist
    #[tracing::instrument(err)]
    pub async fn find(username: &str) -> Result<Self> {
        let connection = zbus::Connection::system()
            .await
            .wrap_err("Could not connect to the system bus")?;
        let accounts = AccountsProxy::new(&connection).await?;

        let path = match accounts.find_user_by_name(username).await {
            Ok(path) => path,
            Err(err) if is_service_unknown(&err) => {
                return Err(eyre!(
                    "accounts-daemon is not available on this host (enable services.yeet.passwordChange)"
                ));
            }
            Err(err) => return Err(err).wrap_err(format!("User {username} does not exist")),
        };

        let proxy = AccountsUserProxy::builder(&connection)
            .path(path)?
            .build()
            .await?;
        Ok(Self { proxy })
    }

    pub async fn info(&self) -> Result<AccountInfo> {
        Ok(AccountInfo {
            uid: self.proxy.uid().await?,
            system_account: self.proxy.system_account().await?,
            local_account: self.proxy.local_account().await?,
        })
    }

    /// Takes a crypt(3) hash, never pass the plaintext in here
    #[tracing::instrument(err, skip(self, hashed_password))]
    pub async fn set_password(&self, hashed_password: &str) -> Result<()> {
        self.proxy
            .set_password(hashed_password, "")
            .await
            .wrap_err("Could not set the password")
    }
}

/// True if nobody owns the bus name we asked for
fn is_service_unknown(err: &zbus::Error) -> bool {
    matches!(err, zbus::Error::MethodError(name, _, _)
        if name.as_str() == "org.freedesktop.DBus.Error.ServiceUnknown")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Needs a running accounts-daemon, run it with
    /// cargo test -p yeet-agent accounts -- --ignored --nocapture
    #[tokio::test]
    #[ignore = "needs accounts-daemon on the system bus"]
    async fn read_own_account() {
        let user = std::env::var("USER").unwrap();
        let account = Account::find(&user).await.unwrap();
        println!("{:?}", account.info().await.unwrap());
    }
}
